class Solution {
public:
    int shareCandies(vector<int>& candies, int k) {
        unordered_map<int, int> remaining;
        for (int x : candies) ++remaining[x];
        int answer = 0;
        for (int i = 0; i < (int)candies.size(); ++i) {
            if (--remaining[candies[i]] == 0) remaining.erase(candies[i]);
            if (i >= k) ++remaining[candies[i - k]];
            if (i >= k - 1) answer = max(answer, (int)remaining.size());
        }
        return k == 0 ? (int)remaining.size() : answer;
    }
};
